import{_ as t,o,c as d,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const p=JSON.parse('{"title":"Plan — FR 3.2.1: Sign Up","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/01-authentication/3-2-1-sign-up/plan.md","filePath":"feature/srs/01-authentication/3-2-1-sign-up/plan.md"}'),a={name:"feature/srs/01-authentication/3-2-1-sign-up/plan.md"};function r(s,e,i,n,l,u){return o(),d("div",null,[...e[0]||(e[0]=[c('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-2-1-sign-up" tabindex="-1">Plan — FR 3.2.1: Sign Up <a class="header-anchor" href="#plan-—-fr-3-2-1-sign-up" aria-label="Permalink to &quot;Plan — FR 3.2.1: Sign Up&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> — Guest email registration with case-insensitive normalization (<code>BR-01</code>), BCrypt cost-12 hashing (<code>BR-02</code>), and 6-digit single-use OTP verification (<code>BR-03</code>, <code>BR-04</code>).</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>GatewayConfig.java</code> (public route <code>/api/v1/auth/register</code>, <code>/verify-otp</code>, <code>/resend-otp</code>), <code>RateLimitGatewayFilterFactory.java</code></td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>controller/auth/AuthController.java</code> (<code>register</code> -&gt; <code>201 CREATED</code>, <code>verifyOtp</code> -&gt; <code>200 OK</code>, <code>resendOtp</code> -&gt; <code>200 OK</code>)</td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>service/impl/auth/AuthServiceImpl.java</code> (<code>register</code>, <code>verifyOtp</code>, <code>resendOtp</code>, <code>generateOtp</code>), <code>service/mail/MailService.java</code></td></tr><tr><td style="text-align:left;"><strong>DTOs &amp; Errors</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>RegisterRequest</code>, <code>RegisterResponse(userId)</code>, <code>VerifyOtpRequest</code>, <code>ForgotPasswordRequest</code>, <code>ErrorCode</code> (<code>EMAIL_ALREADY_EXISTS</code>, <code>OTP_INVALID</code>, <code>OTP_TOO_MANY_ATTEMPTS</code>, <code>RATE_LIMIT_EXCEEDED</code>)</td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>model/user/User.java</code>, <code>model/user/UserSystemRole.java</code>, <code>repository/user/UserRepository.java</code>, <code>UserSystemRoleRepository.java</code>, <code>StringRedisTemplate</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/auth/RegisterPage.tsx</code>, <code>src/pages/auth/VerifyOtpPage.tsx</code>, <code>src/components/auth/{PasswordInput,PasswordStrengthMeter}.tsx</code>, <code>src/services/authService.ts</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>app/(auth)/register.tsx</code>, <code>app/(auth)/verify-otp.tsx</code>, <code>src/services/authService.ts</code></td></tr></tbody></table><h2 id="_2-database-redis-schema" tabindex="-1">2. Database &amp; Redis Schema <a class="header-anchor" href="#_2-database-redis-schema" aria-label="Permalink to &quot;2. Database &amp; Redis Schema&quot;">​</a></h2><ul><li><strong>PostgreSQL <code>users</code>:</strong><ul><li><code>id</code> (<code>UUID</code>, PK), <code>email</code> (<code>VARCHAR(255)</code>, <code>UNIQUE</code> storing normalized lowercase+trimmed email), <code>password_hash</code> (<code>VARCHAR(255)</code>, BCrypt cost 12), <code>full_name</code> (<code>VARCHAR(255)</code>), <code>status</code> (<code>UserStatus.ACTIVE</code>), <code>email_verified_at</code> (<code>TIMESTAMPTZ</code>, nullable until OTP verified), <code>otp_code</code> (<code>VARCHAR(6)</code>, nullable), <code>otp_expiry</code> (<code>TIMESTAMPTZ</code>, 10-minute TTL).</li></ul></li><li><strong>PostgreSQL <code>user_system_roles</code>:</strong><ul><li>Assigns default <code>SystemRole.USER</code> (<code>fk_user_id -&gt; users.id</code>) inside the same <code>@Transactional</code> boundary as user creation.</li></ul></li><li><strong>Redis Ephemeral Keys:</strong><ul><li><code>otp:attempt:&lt;normalizedEmail&gt;</code> — failed OTP verification counter (<code>INCR</code> + <code>EXPIRE 600s</code>; cleared on success or upon hitting 5 failures).</li><li><code>otp:resend:&lt;normalizedEmail&gt;</code> — resend cooldown lock (<code>SETEX 60s</code> -&gt; rejects concurrent resends with <code>429 RATE_LIMIT_EXCEEDED</code>).</li></ul></li></ul><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Registration (<code>POST /api/v1/auth/register</code>):</strong><ul><li>Bean Validation checks <code>fullName</code> (<code>@NotBlank</code>), <code>email</code> (<code>@Email</code>), and <code>password</code> (<code>&gt;= 8</code> chars + <code>&gt;= 1</code> digit) -&gt; <code>400 VALIDATION_ERROR</code> on failure.</li><li><code>AuthServiceImpl.register()</code> normalizes <code>email = request.email().trim().toLowerCase(Locale.ROOT)</code> and trims <code>fullName</code>.</li><li>Hashes password with <code>PasswordEncoder</code> (BCrypt cost 12), generates 6-digit <code>SecureRandom</code> OTP (<code>100000..999999</code>) with <code>otpExpiry = Instant.now().plus(10, MINUTES)</code>, inserts <code>User</code> + <code>UserSystemRole(USER)</code> (catching <code>DataIntegrityViolationException</code> -&gt; <code>409 EMAIL_ALREADY_EXISTS</code>), dispatches OTP email, and returns <code>201 RegisterResponse(userId)</code> without issuing any JWT session.</li></ul></li><li><strong>OTP Verification (<code>POST /api/v1/auth/verify-otp</code>):</strong><ul><li>Normalizes email, loads <code>User</code> (<code>404 USER_NOT_FOUND</code> if absent; idempotent <code>200 OK</code> if <code>emailVerifiedAt != null</code>).</li><li>Validates <code>otpCode != null &amp;&amp; otpExpiry.isAfter(now)</code>; on mismatch increments <code>otp:attempt:&lt;email&gt;</code> (if <code>&lt; 5</code> -&gt; <code>400 OTP_INVALID</code>; on 5th failure -&gt; nulls <code>otpCode</code>/<code>otpExpiry</code>, deletes counter, throws <code>400 OTP_TOO_MANY_ATTEMPTS</code>).</li><li>On match: sets <code>emailVerifiedAt = now</code>, clears <code>otpCode</code>/<code>otpExpiry</code>, deletes Redis counter, returns <code>200 ApiResponse&lt;Void&gt;</code>, and client navigates to <code>/login</code>.</li></ul></li><li><strong>Resend OTP (<code>POST /api/v1/auth/resend-otp</code>):</strong><ul><li>Checks <code>otp:resend:&lt;email&gt;</code> (<code>429 RATE_LIMIT_EXCEEDED</code> if active), generates fresh 6-digit OTP + 10-minute expiry, resets <code>otp:attempt:&lt;email&gt;</code>, sets 60s cooldown key, and sends verification email.</li></ul></li></ol><h2 id="_4-security-concurrency-risks" tabindex="-1">4. Security, Concurrency &amp; Risks <a class="header-anchor" href="#_4-security-concurrency-risks" aria-label="Permalink to &quot;4. Security, Concurrency &amp; Risks&quot;">​</a></h2><ul><li><strong>Race-Safe Uniqueness (<code>BR-01</code>):</strong> Relying on PostgreSQL&#39;s unique constraint on normalized <code>users.email</code> in addition to pre-checks guarantees zero duplicate accounts under concurrent sign-up requests.</li><li><strong>Brute-Force Mitigation (<code>BR-03</code>, <code>BR-04</code>):</strong> Strict 5-attempt OTP invalidation + 60-second Redis cooldown prevents automated enumeration of the 6-digit keyspace.</li><li><strong>No Premature Session Issuance:</strong> <code>RegisterResponse</code> intentionally omits JWT tokens and <code>otpSessionId</code> so unverified accounts cannot access protected routes before proving email ownership.</li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.2.1</code> — Sign Up</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>POST /api/v1/auth/register · POST /api/v1/auth/verify-otp · POST /api/v1/auth/resend-otp</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Guest</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>AuthController</code> -&gt; <code>AuthServiceImpl, MailService</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>users</code>, <code>user_system_roles</code>; Redis <code>otp:attempt:&lt;email&gt;</code>, <code>otp:resend:&lt;email&gt;</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-01, BR-02, BR-03</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>400 VALIDATION_ERROR</code> / <code>OTP_INVALID</code> / <code>OTP_TOO_MANY_ATTEMPTS</code>, <code>409 EMAIL_ALREADY_EXISTS</code>, <code>429 RATE_LIMIT_EXCEEDED</code></td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/auth/RegisterPage.tsx</code>, <code>src/pages/auth/VerifyOtpPage.tsx</code>, <code>src/components/auth/{PasswordInput,PasswordStrengthMeter,AuthBrandPanel}.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>app/(auth)/register.tsx</code>, <code>app/(auth)/verify-otp.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>auth.register.* / auth.verifyOtp.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',15)])])}const h=t(a,[["render",r]]);export{p as __pageData,h as default};
